mapper.select:
SELECT id, dict_type, dict_name, remark, status, create_time FROM sys_dict_type WHERE deleted = 0
AND dict_type LIKE CONCAT('%', #{dictType}, '%')
AND dict_name LIKE CONCAT('%', #{dictName}, '%')
AND status = #{status}
ORDER BY create_time DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE sys_dict_type
SET dict_type = #{dictType}, dict_name = #{dictName}, remark = #{remark}, status = #{status}
WHERE id = #{id}
